<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
const props=defineProps<{reviewId:string;file:any}>(),emit=defineEmits<{close:[]}>();
const url=ref(''),error=ref(''),loading=ref(true),dialog=ref<HTMLElement|null>(null);
const controller=new AbortController();let previous:Element|null=null;
const endpoint=`/api/v1/reviews/${props.reviewId}/materials/${props.file.id}/file`;
function key(event:KeyboardEvent){if(event.key==='Escape')emit('close');if(event.key==='Tab'){const nodes=dialog.value?.querySelectorAll<HTMLElement>('button,a[href],iframe');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
onMounted(async()=>{previous=document.activeElement;dialog.value?.focus();window.addEventListener('keydown',key);try{const res=await fetch(endpoint,{credentials:'include',signal:controller.signal});if(!res.ok){const data=await res.json().catch(()=>({}));throw new Error(res.status===403?'无权访问该材料，或当前阶段已关闭访问。':res.status===404?'文件不存在或已不可用。':data.code??'材料服务暂不可用，请稍后重试。');}const blob=await res.blob();if(!controller.signal.aborted)url.value=URL.createObjectURL(blob);}catch(e:any){if(e.name!=='AbortError')error.value=e.message??'网络异常，文件加载失败。';}finally{loading.value=false;}});
onUnmounted(()=>{controller.abort();if(url.value)URL.revokeObjectURL(url.value);window.removeEventListener('keydown',key);if(previous instanceof HTMLElement)previous.focus();});
</script>
<template><Teleport to="body"><div class="preview-backdrop" @click.self="emit('close')"><section ref="dialog" class="preview-drawer" role="dialog" aria-modal="true" aria-labelledby="preview-title" tabindex="-1"><header><div><h2 id="preview-title">材料预览</h2><p>{{file.fileName}}</p></div><button class="btn" aria-label="关闭材料预览" @click="emit('close')">关闭 ✕</button></header><dl><div><dt>版本</dt><dd>V{{file.version}}</dd></div><div><dt>更新时间</dt><dd>{{new Date(file.createdAt).toLocaleString('zh-CN')}}</dd></div><div><dt>文件大小</dt><dd>{{(file.sizeBytes/1024/1024).toFixed(2)}} MiB</dd></div></dl><p v-if="loading" role="status">正在加载文件…</p><p v-else-if="error" role="alert">{{error}}</p><iframe v-else-if="file.mime==='application/pdf'&&url" :src="url" :title="file.fileName"/><div v-else class="unsupported"><h3>此格式暂不支持在线预览</h3><p>请下载后使用本地办公软件查看。</p><a v-if="url" class="btn btn-primary" :href="url" :download="file.fileName">下载文件</a></div><a v-if="url&&file.mime==='application/pdf'" class="download" :href="url" :download="file.fileName">下载文件</a></section></div></Teleport></template>
<style scoped>
.preview-backdrop{position:fixed;inset:0;background:#172b4d40;z-index:1000;display:flex;justify-content:flex-end}.preview-drawer{background:#fff;width:min(800px,94vw);height:100dvh;box-sizing:border-box;padding:24px;display:flex;flex-direction:column;box-shadow:-8px 0 30px #172b4d18;color:#172b4d;outline:0;overflow:auto}.preview-drawer header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.preview-drawer h2{font-size:20px;margin:0}.preview-drawer p{font-size:13px;color:#667085;overflow-wrap:anywhere}.preview-drawer dl{display:flex;gap:24px;flex-wrap:wrap;padding:16px 0;border-block:1px solid #e5eaf2}.preview-drawer dt{font-size:12px;color:#667085}.preview-drawer dd{margin:5px 0 0;font-size:13px}.preview-drawer iframe{border:1px solid #e5eaf2;border-radius:6px;width:100%;min-height:300px;flex:1;box-sizing:border-box}.unsupported{margin:auto;text-align:center}.download{margin-top:12px;color:#246bfd}
</style>
